    fire("Teleport", a.room)
    task.wait(1.5)
    local t = os.clock()
    while not (CollectionService:GetTagged(a.zone)[1] and CollectionService:GetTagged(a.start)[1]) and os.clock() - t < 6 do task.wait(0.3) end
    local zone, start = CollectionService:GetTagged(a.zone)[1], CollectionService:GetTagged(a.start)[1]
    local model = zone and zone.Parent:FindFirstChild(a.model)
    if not (start and model) then S.bossNote = __T["Boss arena not loaded"] return false end
    local q = model:GetPivot().Position
    local c = Vector3.new(q.X, zone.Position.Y - zone.Size.Y / 2 + 3, q.Z)
    local dir = Vector3.new(start.Position.X - q.X, 0, start.Position.Z - q.Z)
    dir = dir.Magnitude > 0.1 and dir.Unit or Vector3.new(1, 0, 0)
    local spot = c + dir * 10 + Vector3.new(0, 3, 0)
    local function hold()
        local r = M.root()
        if r and ((r.Position - spot) * Vector3.new(1, 0, 1)).Magnitude > 4 then
            r.Anchored = false
            r.AssemblyLinearVelocity = Vector3.zero
            r.CFrame = CFrame.lookAt(spot, Vector3.new(c.X, spot.Y, c.Z))
        end
    end
    hold()
    local done, won = false, false
    local con = RF.BossResult.OnClientEvent:Connect(function(bid, w) if bid == id then done, won = true, w and true or false end end)
    if not join then
        task.wait(0.4)
        fire("BossStart", id)
        t = os.clock()
        while not lp:GetAttribute("BossActive") and os.clock() - t < 10 do hold() task.wait(0.2) end
        if not lp:GetAttribute("BossActive") then con:Disconnect() S.bossNote = name .. __T[" didn't start"] return false end
        pcall(function() require(ReplicatedStorage.BossPrompt).cancel(id) end)
        task.wait((b.intro or 0) + 0.3)
    end
    S.bossNote = "Fighting " .. name
    while not done and RUNNING and lp:GetAttribute("BossActive") and on("bs_on") do
        hold()
        fire("BossSwing")
        task.wait((b.swing or 0.35) + 0.01)
    end
    task.wait(1)
    con:Disconnect()
    return won or lp:GetAttribute(b.key) == true
end
