        pcall(F.openGate, gid, gb, ga)
        F.zoneRoom = nil
        F.busy = false
    end
    local id, b, a = F.bossNext()
    if not id then S.bossNote = nil return end
    local name = tostring(b.name or id)
    local hit = F.hitDamage()
    local swings = math.floor(((b.time or 75) - (b.intro or 0) - 3) / ((b.swing or 0.35) + 0.01))
    local need = (b.hp or math.huge) / math.max(swings, 1)
    if hit < need * 1.05 and lp:GetAttribute("BossActive") ~= true then
        S.bossNote = string.format(__T["%s: hit %s, need %s (%.1fx)"], name, M.fmt(hit), M.fmt(need * 1.05), need * 1.05 / math.max(hit, 1))
        return
    end
    local join = lp:GetAttribute("BossActive") == true
    if F.busy or (M.fighting() and not join) or not F.ready("boss", join and 2 or 30) then return end
    F.busy = true
    local ok, won = pcall(F.bossFight, id, b, a, join)
    if ok and won then
        S.bossNote = __T["Beat "] .. name
        notify(__T["Beat "] .. name)
        task.wait(2)
        pcall(F.openGate, id, b, a)
    elseif ok and S.bossNote == "Fighting " .. name then
        S.bossNote = __T["Lost to "] .. name .. __T[", retrying soon"]
        F.cd.boss = os.clock() + 60
    end
    F.zoneRoom = nil
    F.busy = false
end
