function F.bestRoom(z)
    local best, bs
    for _, r in ipairs(PC.Rooms or {}) do
        if tostring(r.id):match(z.match) and lp:GetAttribute("Room_" .. r.id) == true and (not bs or (r.step or 0) > bs) then best, bs = r.id, r.step or 0 end
    end
