        if set.room == room then
            for i, f in ipairs(set.list or {}) do
                if M.num(M.call(PC.FossilKey, id, i) or "") < (f.max or 0) then return false end
            end
            return true
        end
    end
    return false
end
function F.wormNodeLeft()
    for _, n in ipairs(PC.Tree or {}) do
        if n.currency == "Worms" and lp:GetAttribute("Tree_" .. n.id) ~= true and (not n.rebirth or M.num("Rebirths") >= n.rebirth) then return true end
    end
    return false
