function F.autoZone()
    local fr = F.bestRoom(F.zoneOf("Fossils"))
    if fr and not F.fossilsMaxed(fr) then return "Fossils" end
    if F.bestRoom(F.zoneOf("Worms")) and F.wormNodeLeft() then return "Worms" end
    if F.bestRoom(F.zoneOf("Titles")) then return "Titles" end
    return F.bestRoom(F.zoneOf("Worms")) and "Worms" or "Fossils"
end
function F.pick()
    local p = val("zn_pick", "Auto")
    if p == "Auto" then return F.autoZone(), true end
    local z = F.zoneOf(p)
    if z and not F.bestRoom(z) then return F.autoZone(), true end
    return p, false
end
function F.inZone(part)
    local r = M.root()
    if not (r and part) then return false end
    local rel = part.CFrame:PointToObjectSpace(r.Position)
    local h = part.Size / 2
    return math.abs(rel.X) <= h.X + 0.5 and math.abs(rel.Z) <= h.Z + 0.5 and rel.Y > -h.Y - 2 and rel.Y < h.Y + 8
end
function F.zonePart(z)
    local r = M.root()
    local best, bd
    for _, tag in ipairs(CollectionService:GetAllTags()) do
        if tag:match("^" .. z.tag .. "$") then
            for _, p in ipairs(CollectionService:GetTagged(tag)) do
                if p:IsA("BasePart") then
                    local d = r and (p.Position - r.Position).Magnitude or 0
                    if not bd or d < bd then best, bd = p, d end
                end
            end
        end
    end
    return best, bd
end
