function F.zone()
    if M.fighting() or F.busy then return end
    if F.autoWas == nil then
        F.autoWas = lp:GetAttribute("AutoSteps") == true
        if F.autoWas then fire("SetPref", "AutoSteps", false) lp:SetAttribute("AutoSteps", false) end
    end
    local pick, auto = F.pick()
    if pick ~= "Titles" then pcall(F.rollsOff) end
    local z = F.zoneOf(pick)
    if not z then return end
    local room = F.bestRoom(z)
    if not room then S.zoneNote = "Buy a " .. z.name .. " room first" return end
    if not z.tag then
        if F.zoneRoom == room and F.zoneAt and M.root() and (M.root().Position - F.zoneAt).Magnitude < 150 then S.zoneNote = "Farming " .. z.name return end
        if not F.ready("zonego", 4) then return end
        fire("Teleport", room)
        F.zoneRoom = room
        task.wait(1.5)
        F.zoneAt = M.root() and M.root().Position
        S.zoneNote = "Moved into " .. z.name
        return
    end
    if F.zoneRoom == room then
        local part = F.zonePart(z)
        if part and F.inZone(part) then
            S.zoneNote = (auto and "Auto: " or "") .. "Farming " .. z.name .. " (" .. room .. ")"
            if z.name == "Titles" then F.titleRoll(room) end
            return
        end
    end
    if not F.ready("zonego", 4) then return end
    local part
    if F.zoneRoom ~= room or not F.zonePart(z) or select(2, F.zonePart(z)) > 120 then
        fire("Teleport", room)
        F.zoneRoom = room
        task.wait(1.5)
    end
    part = F.zonePart(z)
    if part and M.root() then
        local top = part.CFrame * CFrame.new(0, part.Size.Y / 2 + 3, 0)
        pcall(function() lp.Character:PivotTo(CFrame.new(top.Position)) end)
        S.zoneNote = "Moved into " .. z.name
    end
end
