    CG:AddLabel('<font color="#f5c542"><b>2026-10-31  v1.0</b></font>', true)
    for _, l in ipairs({ __T["+ Auto steps"], __T["+ Smart buy order"], __T["+ Auto rooms"], __T["+ Auto upgrades"], __T["+ Auto skill tree"], __T["+ Auto specials"], __T["+ Auto rebirth"], __T["+ Worm rebirth"], __T["+ Egg claims"], __T["+ Free rewards"], __T["+ Codes"], __T["+ Zone farming"], __T["+ Auto merchant"], __T["+ Pearl / rite"], __T["+ Auto potions"], __T["+ Room teleports"], __T["+ Anti AFK"] }) do CG:AddLabel(l, true) end
