task.spawn(function()
    S.steps0 = M.num("Steps")
    S.cash0 = M.num("TotalCash")
    while RUNNING do
        pcall(function()
            local mins = math.max((os.clock() - S.t0) / 60, 0.1)
            setText(UI.s1, string.format(__T["Cash %s (+%s/s) · Step %d · %s"], M.fmt(M.num("Cash")), M.fmt(S.rate or 0), M.num("Steps"), tostring(lp.leaderstats and lp.leaderstats:FindFirstChild("Depth") and lp.leaderstats.Depth.Value or "")))
            setText(UI.s2, S.staff and (__T["Paused: dev "] .. S.staff) or (__T["Doing: "] .. S.task))
            local g = (os.clock() - S.msgAt < 8 and S.msg ~= "") and S.msg or ""
            setText(UI.s3, g)
            local note = (on("sb_on") and S.smartNote) or S.stepNote
            if S.saving then note = "Saving for " .. S.saving .. (note and (" · " .. note) or "") end
            setText(UI.dig, string.format(__T["+%d steps this session (%.1f/min) · %d rooms%s"], M.num("Steps") - S.steps0, (M.num("Steps") - S.steps0) / mins, S.rooms, note and ("\n" .. note) or ""))
            setText(UI.rb, (S.bossNote and (S.bossNote .. "\n") or "") .. (S.rebNote or "") .. (S.wNote and ("\n" .. S.wNote) or ""))
            setText(UI.up, string.format(__T["%d upgrades bought"], S.ups))
            setText(UI.tr, string.format(__T["%d nodes bought · Worms %s"], S.nodes, M.fmt(M.num("Worms"))))
            setText(UI.zn, S.zoneNote or "")
            setText(UI.mc, S.merchNote or "")
        end)
        task.wait(0.5)
    end
end)
